// ─── Actualizar una incidencia existente ─────────────────────────────────────
// Acepta: { id, fields, fotos?: [{name,base64,mimeType}], keepUrls?: [string] }
// Si vienen fotos nuevas: las sube a Drive vía Apps Script y compone el CSV
// final Fotos_URLs = keepUrls + nuevas URLs subidas, que se inyecta en fields.

// ─── OBJETOS OLVIDADOS — Google Cloud Storage (objetos/objetos.json) ─────────
// { rows: [{ID, Timestamp, Fecha_encontrado, Fecha_entregado, Entregado_a, Propiedad, '# Departamento', Alojamiento,
//           Reportante, Categoria, Categoria_otro, Descripcion, Lugar_resguardo, Lugar_otro, Comentarios,
//           Fotos_count, Fotos_URLs, Estatus, Reservacion_id, Huesped_nombre, Archivada, Updated_at, UpdatedAt}], migrado }
// Fotos privadas en objetos/fotos/<ID>/… (enlace firmado por /incidencias/foto). La primera lectura copia la hoja «Objetos_Olvidados».
const _OBJ_OBJ = "objetos/objetos.json";
const _OBJ_COLS = { fecha_encontrado: "Fecha_encontrado", fecha_entregado: "Fecha_entregado", entregado_a: "Entregado_a", propiedad: "Propiedad", depto: "# Departamento", alojamiento: "Alojamiento", reportante: "Reportante", categoria: "Categoria", categoria_otro: "Categoria_otro", descripcion: "Descripcion", lugar_resguardo: "Lugar_resguardo", lugar_otro: "Lugar_otro", comentarios: "Comentarios", estatus: "Estatus", reserva: "Reservacion_id", huesped: "Huesped_nombre", archivada: "Archivada", fecha_reporte: "Fecha_reporte", fecha_estancia: "Fecha_estancia" };
const _objSt = { d: null, ts: 0, mig: null };
function _objEst(v, entregado) { const s = String(v || "").trim(); return /entreg/i.test(s) ? "Entregado" : /desech|don/i.test(s) ? "Desechado" : /proceso|contact|env/i.test(s) ? "En proceso" : s ? "Resguardado" : (String(entregado || "").trim() ? "Entregado" : "Resguardado"); }
async function _objGuardarFoto(id, buf, ct, nombre) {
  const ext = (String(ct).split("/")[1] || "jpg").replace(/[^a-z0-9]/gi, "").slice(0, 5) || "jpg";
  const nom = String(nombre || `foto.${ext}`).replace(/[^\w.\- ()áéíóúñÁÉÍÓÚÑ]/g, "_").slice(0, 80);
  const k = `objetos/fotos/${String(id).replace(/[^\w-]/g, "")}/${Date.now().toString(36)}-${crypto.randomBytes(3).toString("hex")}-${nom}`;
  await _rhdPut(k, buf, ct || "image/jpeg");
  return _incFotoUrl(k);
}
async function _objSubirFotos(id, fotos) {
  const L = await Promise.all((fotos || []).map(async f => {
    if (!f || !f.base64) return null;
    try { const buf = Buffer.from(String(f.base64).replace(/^data:[^,]*,/, ""), "base64"); if (!buf.length || buf.length > 20 * 1024 * 1024) return null; return await _objGuardarFoto(id, buf, f.mimeType || "image/jpeg", f.name); }
    catch (e) { console.warn("[obj] foto no subida:", e.message); return null; }
  }));
  return L.filter(Boolean);
}
// Migración única desde la hoja (si ya hay datos en Cloud Storage no hace nada, salvo force).
function _objMigrar(force) {
  if (_objSt.mig) return _objSt.mig;
  _objSt.mig = (async () => {
    const actual = await _rhdGetJson(_OBJ_OBJ);
    if (Array.isArray(actual.rows) && !force) return actual;
    const src = await callCheckinAppsScript("list_objetos");
    if (!src || src.ok === false || !Array.isArray(src.rows)) throw new Error("No se pudo leer la hoja Objetos_Olvidados: " + ((src && src.error) || "sin datos"));
    let fotos = 0, fallidas = 0; const rows = [];
    for (const r0 of src.rows) {
      const r = Object.assign({}, r0); if (!String(r.ID || "").trim()) continue;
      const urls = String(r.Fotos_URLs || "").split(",").map(x => x.trim()).filter(Boolean), nuevas = [];
      for (const u of urls) {
        const img = await _incBajarImagen(u);
        if (img) { try { nuevas.push(await _objGuardarFoto(r.ID, img.buf, img.ct)); fotos++; continue; } catch (_) {} }
        fallidas++; nuevas.push(u); // si Drive no la entrega se conserva el enlace original
      }
      if (urls.length) { r.Fotos_URLs_drive = urls.join(", "); r.Fotos_URLs = nuevas.join(", "); r.Fotos_count = String(nuevas.length); }
      r.Estatus = _objEst(r.Estatus, r.Fecha_entregado);
      rows.push(r);
    }
    rows.sort((a, b) => String(b.Timestamp || "").localeCompare(String(a.Timestamp || "")));
    const d = { rows, migrado: { at: new Date().toISOString(), desde: "Hoja «Objetos_Olvidados» (Apps Script)", n: rows.length, fotos, fallidas } };
    await _aseoMutate(_OBJ_OBJ, "objData", x => { for (const k of Object.keys(x)) delete x[k]; Object.assign(x, d); });
    console.log(`[obj] migración: ${rows.length} objetos, ${fotos} fotos copiadas, ${fallidas} sin copiar`);
    return d;
  })().finally(() => { _objSt.mig = null; });
  return _objSt.mig;
}
async function _objDatos(fresco) {
  if (!fresco && _objSt.d && Date.now() - _objSt.ts < 5_000) return _objSt.d;
  let d = await _rhdGetJson(_OBJ_OBJ);
  if (!Array.isArray(d.rows)) d = await _objMigrar();
  _objSt.d = d; _objSt.ts = Date.now();
  return d;
}
function _objMutar(fn) {
  return _objDatos(true).then(() => _aseoMutate(_OBJ_OBJ, "objData", d => { if (!Array.isArray(d.rows)) d.rows = []; return fn(d); }))
    .then(out => { _objSt.d = _aseo.objData; _objSt.ts = Date.now(); return out; });
}
app.get("/objetos-list", async (req, res) => {
  try {
    const d = await _objDatos(req.query.fresh === "1");
    const rows = (d.rows || []).map(r => Object.assign({}, r, { Estatus: _objEst(r.Estatus, r.Fecha_entregado) })).sort((a, b) => String(b.Timestamp || "").localeCompare(String(a.Timestamp || "")));
    res.json({ ok: true, rows, total: rows.length, origen: "gcs", migrado: d.migrado || null });
  } catch (err) { res.status(500).json({ ok: false, error: err.message }); }
});
app.post("/objetos/migrar", async (req, res) => {
  if (!process.env.SYNC_SECRET || (req.get("X-Sync-Secret") || "") !== process.env.SYNC_SECRET) return res.status(401).json({ ok: false, error: "unauthorized" });
  try { const d = await _objMigrar(req.query.force === "1"); _objSt.d = null; res.json({ ok: true, migrado: d.migrado || null, total: (d.rows || []).length }); }
  catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post("/save-objeto", async (req, res) => {
  try {
    const p = req.body?.payload || {};
    const now = _incMxNow();
    const id = `OBJ-${now.slice(0, 10).replace(/-/g, "")}-${now.slice(11).replace(/:/g, "")}-${Math.floor(Math.random() * 10000)}`;
    const fotos = await _objSubirFotos(id, Array.isArray(req.body?.fotos) ? req.body.fotos : []);
    const row = { ID: id, Timestamp: now };
    Object.keys(_OBJ_COLS).forEach(k => { row[_OBJ_COLS[k]] = _incCsv(p[k] != null ? p[k] : p[_OBJ_COLS[k]]); });
    if (!row.Alojamiento) row.Alojamiento = row.Propiedad && row["# Departamento"] ? `${row.Propiedad} - #${row["# Departamento"]}` : row.Propiedad;
    row.Estatus = _objEst(row.Estatus, row.Fecha_entregado);
    row.Fotos_count = String(fotos.length); row.Fotos_URLs = fotos.join(", "); row.Updated_at = ""; row.UpdatedAt = new Date().toISOString();
    await _objMutar(d => { d.rows.unshift(row); });
    try { _histAdd("O:" + id, [["Registrado", "", row.Categoria || "Objeto"]], String(req.body?.user || row.Reportante || "")); } catch (_) {}
    res.json({ ok: true, id, timestamp: now, fotos_uploaded: fotos.length, row });
  } catch (err) {
    console.error("save_objeto_error", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});
// Edición: solo cambia los campos recibidos (claves en minúsculas o encabezados). Fotos: keepUrls + nuevas.
app.post("/update-objeto", async (req, res) => {
  try {
    const id = String(req.body?.id || "").trim();
    const fields = Object.assign({}, req.body?.fields || {});
    const newFotos = Array.isArray(req.body?.fotos) ? req.body.fotos : null;
    const keepUrls = Array.isArray(req.body?.keepUrls) ? req.body.keepUrls : null;
    if (!id) return res.status(400).json({ ok: false, error: "Falta id" });
    const subidas = newFotos ? await _objSubirFotos(id, newFotos) : [];
    let final = null, cambios = [];
    const NOM = { Fecha_reporte: "Fecha de reporte", Fecha_encontrado: "Fecha encontrado", Fecha_entregado: "Fecha entregado", Entregado_a: "Entregado a", Alojamiento: "Alojamiento", Reportante: "Reportó", Categoria: "Categoría", Descripcion: "Descripción", Lugar_resguardo: "Lugar de resguardo", Comentarios: "Comentarios", Estatus: "Estado", Archivada: "Archivada" };
    const ok = await _objMutar(d => {
      const r = d.rows.find(x => String(x.ID) === id); if (!r) return false;
      Object.keys(fields).forEach(k => {
        const col = _OBJ_COLS[k] || (Object.values(_OBJ_COLS).includes(k) ? k : null); if (!col) return;
        const v = col === "Estatus" ? _objEst(fields[k]) : _incCsv(fields[k]);
        if (String(r[col] || "") !== v && NOM[col]) cambios.push([NOM[col], r[col] || "", v]);
        r[col] = v;
      });
      if (newFotos !== null || keepUrls !== null) {
        final = (keepUrls || String(r.Fotos_URLs || "").split(",").map(x => x.trim()).filter(Boolean)).concat(subidas);
        if (String(final.length) !== String(r.Fotos_count || "0")) cambios.push(["Fotos", r.Fotos_count || "0", String(final.length)]);
        r.Fotos_URLs = final.join(", "); r.Fotos_count = String(final.length);
      }
      r.Updated_at = _incMxNow(); r.UpdatedAt = new Date().toISOString();
      return true;
    });
    if (!ok) return res.status(404).json({ ok: false, error: "ID no encontrado: " + id });
    try { if (cambios.length) _histAdd("O:" + id, cambios, String(req.body?.user || "")); } catch (_) {}
    const out = { ok: true, id };
    if (final) { out.fotos_urls = final.join(", "); out.fotos_count = final.length; }
    res.json(out);
  } catch (err) {
    console.error("update_objeto_error", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ─── Listar reportes de incidencias guardados ────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
// ║ REPORTES TÉCNICOS (MVP F1) — passthrough a Apps Script                  ║
// ═══════════════════════════════════════════════════════════════════════════
const _rtLista = { ts: 0, payload: null, p: null };
function _rtListaCargar() {
  if (!_rtLista.p) _rtLista.p = callCheckinAppsScriptPost("rt_list", {}).then(r => { if (r && r.ok !== false && Array.isArray(r.rows)) { _rtLista.payload = r; _rtLista.ts = Date.now(); } return r; }).finally(() => { _rtLista.p = null; });
  return _rtLista.p;
}
app.get("/reportes-tecnicos-list", async (req, res) => {
  try {
    if (_rtLista.payload && req.query.fresh !== "1") {
      if (Date.now() - _rtLista.ts > 30_000) _rtListaCargar().catch(() => {}); // se refresca sin hacer esperar
      return res.json(_rtLista.payload);
    }
    res.json(await _rtListaCargar());
  } catch (err) { res.status(500).json({ ok: false, error: err.message }); }
});
// Enlace de un reporte técnico NUEVO con su incidencia (tarea correctiva): tipo de servicio + incidencia en aseo/extra.json
// y «Tarea_ligada» en la incidencia. Lo hace el servidor para que no dependa de que la pantalla siga abierta.
async function _rtLigar(id, liga, user) {
  const k = "R" + id, incId = String(liga.incId || "").replace(/[^\w-]/g, "").slice(0, 60), srv = String(liga.srv || "correctivo");
  await _aseoMutate(_ASEO_EXTRA_OBJ, "extra", d => {
    const cur = d[k] || {}; cur.checkout = srv === "checkout"; cur.correctivo = srv === "correctivo"; cur.preventivo = srv === "preventivo";
    if (incId) { cur.incidencia = true; cur.incId = incId; cur.incIds = [incId]; cur.deInc = true; cur.incBy = user; cur.incAt = new Date().toISOString(); }
    Object.assign(cur, { by: user, at: new Date().toISOString() }); d[k] = cur;
  });
  _aseo.extraTs = Date.now();
  if (incId) await _incMutar(dd => { const r = (dd.rows || []).find(x => String(x.ID) === incId); if (!r) return; const L = String(r.Tarea_ligada || "").split(/\s*,\s*/).filter(Boolean); if (!L.includes(k)) L.push(k); r.Tarea_ligada = L.join(", "); r.UpdatedAt = new Date().toISOString(); });
}
app.post("/reportes-tecnicos-upsert", async (req, res) => {
  // bg=1 (alta desde «Crear tarea correctiva»): la hoja de Google tarda 15–45 s en guardar el reporte; se responde de
  // inmediato y el alta + el enlace con la incidencia se terminan en segundo plano (Cloud Run sin límite de CPU).
  const bg = !!req.body?.bg && !(req.body?.payload || {}).ID, liga = req.body?.liga || null;
  if (bg) {
    res.json({ ok: true, pending: true });
    req.body.bg = false;
    const fakeRes = { json: o => { if (o && o.ok && o.id && liga) _rtLigar(String(o.id), liga, String((req.body.payload || {}).Updated_by || "")).catch(e => console.warn("[rt] enlace correctiva:", e.message)); if (!o || !o.ok) console.warn("[rt] alta en 2º plano falló:", o && o.error); }, status: () => fakeRes };
    return _rtUpsertHandler(req, fakeRes);
  }
  return _rtUpsertHandler(req, res);
});
async function _rtUpsertHandler(req, res) {
  try {
    const payload = req.body?.payload || {};
    const fotosAntes = Array.isArray(req.body?.fotos_antes) ? req.body.fotos_antes : [];
    const fotosDespues = Array.isArray(req.body?.fotos_despues) ? req.body.fotos_despues : [];
    const uploadAll = async (list) => Promise.all(list.filter(f => f && f.base64).map(async f => {
      try {
        const buf = Buffer.from(String(f.base64).replace(/^data:[^,]*,/, ""), "base64");
        const nombre = String(f.name || "foto.jpg").replace(/[^\w.\- ()áéíóúñÁÉÍÓÚÑ]/g, "_").slice(0, 100);
        const k = `aseo/adjuntos/rt-${Date.now().toString(36)}-${crypto.randomBytes(3).toString("hex")}-${nombre}`;
        await _rhdPut(k, buf, f.mimeType || "image/jpeg");
        return `https://api.check-inn.mx/aseo/adjunto?k=${encodeURIComponent(k)}&s=${_aseoAdjSig(k)}`;
      } catch (e) { console.warn("rt foto no subida:", e.message); return null; }
    })).then(L => L.filter(Boolean));
    const uploadAllViejo = async (list) => {
      const urls = [];
      for (const f of list) {
        if (!f || !f.base64) continue;
        const up = await callCheckinAppsScriptPost("rt_upload_image", {
          name: f.name || `rt_${Date.now()}.jpg`,
          mimeType: f.mimeType || "image/jpeg",
          base64: f.base64,
        });
        if (up && up.ok && up.url) { urls.push(up.url); continue; }
        console.warn("rt upload failed:", JSON.stringify(up).slice(0, 200));
        // Respaldo: si Drive (Apps Script) falla, la foto se guarda privada en Cloud Storage con enlace firmado.
        try {
          const buf = Buffer.from(String(f.base64).replace(/^data:[^,]*,/, ""), "base64");
          const nombre = String(f.name || "foto.jpg").replace(/[^\w.\- ()áéíóúñÁÉÍÓÚÑ]/g, "_").slice(0, 100);
          const k = `aseo/adjuntos/rt-${Date.now().toString(36)}-${crypto.randomBytes(3).toString("hex")}-${nombre}`;
          await _rhdPut(k, buf, f.mimeType || "image/jpeg");
          urls.push(`https://api.check-inn.mx/aseo/adjunto?k=${encodeURIComponent(k)}&s=${_aseoAdjSig(k)}`);
        } catch (e) { console.warn("rt upload respaldo falló:", e.message); }
      }
      return urls;
    };
    const [antes, despues] = await Promise.all([uploadAll(fotosAntes), uploadAll(fotosDespues)]);
    // Preservar URLs previas si vienen (edición) + append de nuevas.
    // Solo tocar Fotos_*_urls si el payload las trae o si hay fotos nuevas —
    // patches parciales (ej. cambio de Fecha) NO deben borrar fotos existentes.
    const prevAntes = String(payload.Fotos_antes_urls || "").split(",").map(s => s.trim()).filter(Boolean);
    const prevDespues = String(payload.Fotos_despues_urls || "").split(",").map(s => s.trim()).filter(Boolean);
    const finalPayload = { ...payload };
    if (antes.length || "Fotos_antes_urls" in payload) {
      finalPayload.Fotos_antes_urls = [...prevAntes, ...antes].join(",");
    }
    if (despues.length || "Fotos_despues_urls" in payload) {
      finalPayload.Fotos_despues_urls = [...prevDespues, ...despues].join(",");
    }
    const rtPrev = payload.ID ? ((await _clRtRows().catch(() => [])).find(x => String(x.ID) === String(payload.ID)) || null) : null;
    let r;
    if (!payload.ID) {
      // ALTA: Apps Script a veces responde HTML aunque SÍ guardó la fila → un reintento ciego duplicaba el reporte
      // (pasó con «fuga de agua» RT-2026-000022/23). Un intento; si falla, se busca la fila antes de reintentar.
      const t0 = Date.now();
      const buscar = async () => {
        const L = await callCheckinAppsScriptPost("rt_list", {}).catch(() => null);
        const f = ((L && L.rows) || []).find(x => String(x.Titulo || "") === String(finalPayload.Titulo || "") && String(x.Fecha || "").slice(0, 10) === String(finalPayload.Fecha || "").slice(0, 10)
          && String(x.Reportado_por || "") === String(finalPayload.Reportado_por || "") && Number((String(x.ID || "").match(/^RT(\d+)/) || [])[1] || 0) >= t0 - 120_000); // el ID lleva la hora de alta (ms)
        return f ? { ok: true, id: f.ID, folio: f.Folio, dedupe: true } : null;
      };
      for (let i = 0; i < 3 && !(r && r.ok); i++) {
        r = await callCheckinAppsScriptPost("rt_upsert", finalPayload, { max: 1 }).catch(e => ({ ok: false, error: e.message }));
        if (r && r.ok) break;
        await new Promise(x => setTimeout(x, 2000 * (i + 1)));
        const f = await buscar(); if (f) { r = f; break; }
      }
    } else r = await callCheckinAppsScriptPost("rt_upsert", finalPayload);
    if (!r || !r.ok) throw new Error(r?.error || "upsert failed");
    _rtLista.payload = null; _rtListaCargar().catch(() => {}); // la siguiente lectura trae el cambio
    try { // historial del reporte de Mantenimiento
      const who = payload.Updated_by || payload.Reportado_por || "", rid = String(r.id || payload.ID || "");
      const EST = { nuevo: "Pendiente", pendiente: "Pendiente", en_proceso: "En proceso", resuelto: "Terminado", cancelado: "Cancelado" };
      if (!payload.ID) _histAdd("R:" + rid, [["Creado", "", payload.Titulo || "Reporte técnico"]], who);
      else if (rtPrev) {
        const C = [["Estado", "Estado"], ["Prioridad", "Prioridad"], ["Titulo", "Título"], ["Descripcion", "Descripción"], ["Asignado_a", "Asignados"], ["Fecha", "Fecha"], ["Fecha_compromiso", "Compromiso"], ["Categoria", "Categoría"],
          ["Bloquea_habitabilidad", "Bloquea habitabilidad"], ["Reincidente", "Reincidente"], ["Descripcion_solucion", "Solución"], ["Costo_total", "Costo"], ["Proveedor", "Proveedor"], ["Responsabilidad", "Responsabilidad"]];
        const v = (k, x) => { x = String(x == null ? "" : x); if (k === "Estado") return EST[x.toLowerCase()] || x; if (/Fecha/.test(k)) return x.slice(0, 10); if (k === "Bloquea_habitabilidad" || k === "Reincidente") return /^(true|s[ií]|1)$/i.test(x) ? "Sí" : "No"; return x; };
        _histAdd("R:" + rid, C.filter(([k]) => k in payload).map(([k, t]) => [t, v(k, rtPrev[k]), v(k, payload[k])]), who);
        Object.assign(rtPrev, payload); // la copia en memoria queda al día para el siguiente cambio
      }
    } catch (_) {}
    res.json({ ...r, fotos_antes_uploaded: antes.length, fotos_despues_uploaded: despues.length });
  } catch (err) { res.status(500).json({ ok: false, error: err.message }); }
}
app.post("/reportes-tecnicos-delete", async (req, res) => {
  try {
    const id = String(req.body?.id || "").trim();
    if (!id) return res.status(400).json({ ok: false, error: "id requerido" });
    const r = await callCheckinAppsScriptPost("rt_delete", { id });
    _rtLista.payload = null; _rtListaCargar().catch(() => {});
    res.json(r);
  } catch (err) { res.status(500).json({ ok: false, error: err.message }); }
});


// ─── Guardar reporte de incidencia ───────────────────────────────────────────
// Recibe { payload: {fecha, propiedad, depto, ...}, fotos: [{name, base64, mimeType}] }
// 1) Sube cada foto via Apps Script → DriveApp en /Drive/Incidencias/{año}/{mes}
// 2) Inserta una fila en la hoja "Incidencias" con las URLs públicas

// Caché stale-while-revalidate para endpoints de una sola consulta: responde
// al instante con la última respuesta buena y refresca en segundo plano.
// Solo espera a Apps Script si nunca ha habido respuesta buena.
function _swrCache(fetcher, freshMs, staleMs) {
  const st = { ts: 0, payload: null, inflight: null };
  const refresh = () => {
    if (!st.inflight) {
      st.inflight = fetcher()
        .then(p => { if (p && p.ok !== false) { st.payload = p; st.ts = Date.now(); } return p; })
        .finally(() => { st.inflight = null; });
    }
    return st.inflight;
  };
  const get = async () => {
    const age = Date.now() - st.ts;
    if (st.payload && age < freshMs) return { ...st.payload, cached: true, cached_age_ms: age };
    if (st.payload && age < staleMs) {
      refresh().catch(() => {});
      return { ...st.payload, cached: true, stale: true, cached_age_ms: age };
    }
    return await refresh();
  };
  return { get, refresh };
}

const _huFilterOptionsCache = _swrCache(() => callCheckinAppsScript("list_filter_options"), 30 * 60_000, 7 * 24 * 60 * 60_000);
