const _HUR_OBJ = "config/hu-reglas.json";
const _HUR_KEYS = ["oro", "plata", "bronce", "recurrente", "w_noches", "w_visitas", "w_monto", "ref_noches", "ref_visitas", "ref_monto", "primera_max_visitas", "larga_noches", "mensual_noches"];
