      // Plan asignado (copia al oprimir «Asignar»): { prog: { dia, tareas: [...] } } · limpiar avisos: { progCambiosClear: dia }
      if (B.prog && /^\d{4}-\d{2}-\d{2}$/.test(String(B.prog.dia || "")) && Array.isArray(B.prog.tareas)) { d.prog = d.prog || {}; const prevP = (d.prog || {})[B.prog.dia] || {}, ahoraP = new Date().toISOString(); d.prog[B.prog.dia] = { at: ahoraP, by: txt(B.user), enfoque: String(B.prog.enfoque || prevP.enfoque || "param").slice(0, 20), acept: String(B.prog.acept || prevP.acept || ahoraP).slice(0, 30), retrasos: (B.prog.retrasos && typeof B.prog.retrasos === "object") ? Object.fromEntries(Object.entries(B.prog.retrasos).slice(0, 60).map(([k, v]) => [String(k).slice(0, 40), { min: Number(v && v.min) || 0, extra: v && v.extra != null ? Number(v.extra) : undefined, desde: v && v.desde != null ? Number(v.desde) : undefined, motivo: String((v && v.motivo) || "").slice(0, 60), at: String((v && v.at) || ahoraP).slice(0, 30) }])) : (prevP.retrasos || {}), tareas: B.prog.tareas.slice(0, 200).map(x => ({ id: String(x.id || "").slice(0, 40), asigId: String(x.asigId || "").slice(0, 40), tid: String(x.tid || "").slice(0, 40), hid: String(x.hid || "").slice(0, 20), cod: String(x.cod || "").slice(0, 20), quienN: String(x.quienN || "").slice(0, 80), rol: x.rol === "inspeccion" ? "inspeccion" : "aseo", ini: Number(x.ini) || 0, fin: Number(x.fin) || 0, tipoT: String(x.tipoT || "").slice(0, 20), prop: String(x.prop || "").slice(0, 60) })) }; if (d.progCambios) delete d.progCambios[B.prog.dia]; }
      if (/^\d{4}-\d{2}-\d{2}$/.test(String(B.progCambiosClear || "")) && d.progCambios) delete d.progCambios[B.progCambiosClear];
      { const lim = new Date(Date.now() - 4 * 864e5).toISOString().slice(0, 10); ["prog", "progCambios"].forEach(k => { if (d[k]) Object.keys(d[k]).forEach(f => { if (f < lim) delete d[k][f]; }); }); }
      if (B.insp_min != null && isFinite(Number(B.insp_min)) && Number(B.insp_min) > 0) d.insp_min = Math.min(240, Math.round(Number(B.insp_min))); // b.1) duración de inspección
      if (B.pesos && typeof B.pesos === "object") { d.pesos = d.pesos || {}; Object.keys(B.pesos).slice(0, 30).forEach(k => { const v = Number(B.pesos[k]); if ([0, 1, 2, 3, 4, 5].includes(v)) d.pesos[String(k).slice(0, 20)] = v; }); } // fuerza de cada prioridad
