    const code = String(r.device_name || r.Device_name || "").trim();
    const hid = String(r.HouseId || r.id_lodgify || "").replace(/\D/g, "") || (code ? _hidSint(code) : "");
    const pn = _botNorm(prop).replace(/^(calle|av|avenida|plaza|privada)\s+/, "");
