  toc: { obj: "checklist/tareas-ocurrencias.json",  src: "tareas_ocur_list" },
  thi: { obj: "checklist/tareas-historial.json",    src: "tareas_hist_list" },
  sol: { obj: "whatsapp/solicitudes.json",          src: "list_solicitudes" },
