    L.push(`• *${[I.aloj, I.titulo].filter(Boolean).join(" · ") || "Incidencia"}*`); p.det.forEach(d => L.push(`   ${d}`));
    if (I.estatus || I.nivel) L.push(`   Ahora: ${[I.estatus, I.nivel ? "nivel " + String(I.nivel).toLowerCase() : ""].filter(Boolean).join(" · ")}`);
