    procs.forEach(k => { _bcLog({ tipo: action === "skip" ? "rechazo" : action === "edit" ? "edicion" : "aprobacion", conv, proceso: k, usuario: usuario || "" }); if (action === "skip") _bcFallo(k, "rechazos en la cola"); });
